import java.util.*;
import java.io.*;

public class Main {
    static final int maxn = 5005;
    static final int K = 100;
    static final int INF = 1000000007;

    static class Edge {
        int u, v;
        int cap, flow;
        int cost;

        Edge(int u, int v, int cap, int flow, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static class MCMF {
        int n, m, s, t;
        ArrayList<Integer>[] G;
        ArrayList<Edge> E;
        int[] p, inq, d, a;

        @SuppressWarnings("unchecked")
        MCMF(int n) {
            this.n = n;
            G = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                G[i] = new ArrayList<>();
            }
            E = new ArrayList<>();
            p = new int[n];
            inq = new int[n];
            d = new int[n];
            a = new int[n];
        }

        void addEdge(int u, int v, int cap, int cost) {
            E.add(new Edge(u, v, cap, 0, cost));
            E.add(new Edge(v, u, 0, 0, -cost));
            m = E.size();
            G[u].add(m - 2);
            G[v].add(m - 1);
        }

        boolean BelmanFord(int[] flowArr, int[] costArr) {
            Arrays.fill(d, INF);
            Arrays.fill(inq, 0);
            d[s] = 0;
            inq[s] = 1;
            p[s] = -1;
            a[s] = Integer.MAX_VALUE;

            Queue<Integer> Q = new LinkedList<>();
            Q.offer(s);
            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = 0;
                for (int i : G[u]) {
                    Edge e = E.get(i);
                    if (e.cap > e.flow && d[e.v] > d[u] + e.cost) {
                        d[e.v] = d[u] + e.cost;
                        p[e.v] = i;
                        a[e.v] = Math.min(a[u], e.cap - e.flow);
                        if (inq[e.v] == 0) {
                            Q.offer(e.v);
                            inq[e.v] = 1;
                        }
                    }
                }
            }
            if (d[t] == INF) return false;
            flowArr[0] = a[t];
            costArr[0] = d[t];
            int u = t;
            while (u != s) {
                int i = p[u];
                E.get(i).flow += a[t];
                E.get(i ^ 1).flow -= a[t];
                u = E.get(i).u;
            }
            return true;
        }

        Pair<Integer, Integer> Mincost(int s, int t) {
            this.s = s;
            this.t = t;
            int totalFlow = 0;
            int totalCost = 0;
            int[] f = new int[1];
            int[] c = new int[1];
            while (BelmanFord(f, c)) {
                totalFlow += f[0];
                totalCost += f[0] * c[0];
            }
            return new Pair<>(totalFlow, totalCost);
        }
    }

    static class Pair<U, V> {
        public final U first;
        public final V second;

        public Pair(U first, V second) {
            this.first = first;
            this.second = second;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int totalNodes = n * K + 2;
        MCMF solver = new MCMF(totalNodes);
        int source = n * K;
        int sink = n * K + 1;

        for (int i = 0; i < K; i++) {
            solver.addEdge(i, sink, k, C * i);
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            x--;
            solver.addEdge(source, x * K, 1, 0);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < K; j++) {
                solver.addEdge(i * K + j - 1, i * K + j, k, 0);
            }
        }

        for (int _ = 0; _ < m; _++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            u--;
            v--;
            for (int j = 1, cc = D; j <= k; j++, cc += 2 * D) {
                int a = u * K + j - 1;
                int b = v * K + j;
                int c = v * K + j - 1;
                int d = u * K + j;
                solver.addEdge(a, b, 1, cc);
                solver.addEdge(c, d, 1, cc);
            }
        }

        Pair<Integer, Integer> pr = solver.Mincost(source, sink);
        System.out.println(pr.second);
        sc.close();
    }
}
